"use client"

import * as React from "react"
import { CircleAlert, CircleCheck, Copy, EyeOff, FileWarning, Info, TriangleAlert, WandSparkles } from "lucide-react"

import { cn } from "@/lib/utils"
import { checkGitignore, checkIgnore, parseFileList, parseGitignore, sensitiveKind, toLines, untrackCommand, type GitignoreIssue } from "@/registry/default/gitignore-check/gitignore"

export { checkGitignore, checkIgnore, parseFileList, parseGitignore, patternToRegex, sensitiveKind, trimTrailingSpaces, untrackCommand, type FileEntry, type GitignoreIssue, type GitignoreIssueKind, type GitignoreRule, type IgnoreVerdict } from "@/registry/default/gitignore-check/gitignore"

export const GITIGNORE_CHECK_MESSAGES = {
  label: ".gitignore",
  placeholder: "node_modules/\n.env",
  clean: "No problems found.",
  problems: "{errors} to fix · {warnings} to review",
  line: "Line {line}",
  selectLine: "Select line {line}",
  fixAll: "Fix {count}",
  fix: "Fix",
  "inline-comment": "# only starts a comment at the beginning of a line, so Git looks for a file literally named \"{detail} # …\" and ignores nothing.",
  "fix-inline-comment": "Remove the comment",
  "trailing-tab": "Ends in a tab or non-breaking space. Git only trims plain spaces, so this pattern never matches.",
  "trailing-space": "Trailing spaces. Git trims these, so it still works.",
  "fix-trailing-space": "Trim",
  "leading-space": "Starts with a space, so it only matches names that start with a space.",
  "fix-leading-space": "Remove the space",
  backslash: "Backslash escapes the next character in .gitignore; folders are separated with /.",
  "fix-backslash": "Use /",
  "dot-slash": "Git doesn't understand ./ here, so this matches nothing. Use / to mean the repo root.",
  "fix-dot-slash": "Use /",
  "dir-blocks-negation": "This ! can't re-include the file: {detail} excludes its whole folder, and Git never looks inside an excluded folder.",
  "fix-dir-blocks-negation": "Ignore the folder's contents instead",
  "negation-overridden": "{detail} comes later and ignores this file again. The last matching line wins.",
  "fix-negation-overridden": "Move below it",
  "anchored-misses": "The leading / only matches at the repo root, so {detail} isn't ignored.",
  "fix-anchored-misses": "Match at any depth",
  "not-ignored": "Not ignored, so it would be committed: {detail}.",
  "fix-not-ignored": "Add to .gitignore",
  tracked: "Already committed. .gitignore doesn't untrack files, so Git keeps tracking these:",
  trackedSecret: "Committed secrets stay in history: rotate them after untracking.",
  copyCommand: "Copy git rm --cached",
  copied: "Copied",
  copiedStatus: "Command copied. Run it, then commit.",
  copyFailed: "Couldn't reach the clipboard. Select the command and copy it.",
  filesLabel: "Test your files",
  filesHint: "Paste paths, git ls-files or git status --porcelain output.",
  filesPlaceholder: ".env\nsrc/index.ts",
  trackedLabel: "These paths are already committed",
  results: "{ignored} of {total} ignored",
  ignoredBy: "Ignored · line {line}: {rule}",
  ignoredDir: "Ignored with its folder {dir}/ · line {line}: {rule}",
  blocked: "Still ignored · line {neg} can't re-include it",
  includedBy: "Kept · line {line}: {rule}",
  kept: "Not ignored",
  stillTracked: "Ignored, but still tracked",
  more: "+{count} more",
}
export type GitignoreCheckMessages = typeof GITIGNORE_CHECK_MESSAGES

const fill = (text: string, values: Record<string, string | number>) => text.replace(/\{(\w+)\}/g, (match, key: string) => String(values[key] ?? match))
const tones = { error: "text-red-700 dark:text-red-400", warning: "text-amber-700 dark:text-amber-400", info: "text-muted-foreground" }
const icons = { error: CircleAlert, warning: TriangleAlert, info: Info }
const fixClass = (error: boolean) =>
  cn(
    "inline-flex min-h-6 max-w-full items-center gap-1 rounded-md border px-2 text-left font-medium [overflow-wrap:anywhere] transition-colors outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:opacity-50",
    error ? "border-red-500/40 text-red-800 hover:bg-red-500/10 dark:text-red-200" : "border-amber-500/40 text-amber-900 hover:bg-amber-500/10 dark:text-amber-200",
  )
const area = "w-full min-w-0 resize-y rounded-md border bg-transparent px-3 py-2 font-mono text-base leading-5 shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive md:text-xs dark:bg-input/30"
const SHOWN = 40

function useSettled(text: string, delay = 900) {
  const [settled, setSettled] = React.useState(text)
  React.useEffect(() => {
    const timer = setTimeout(() => setSettled(text), delay)
    return () => clearTimeout(timer)
  }, [text, delay])
  return settled
}

export interface GitignoreCheckProps extends Omit<React.ComponentProps<"textarea">, "value" | "defaultValue" | "onChange"> {
  /** Controlled .gitignore text. */
  value?: string
  /** Initial .gitignore text when uncontrolled. */
  defaultValue?: string
  /** Called with the new text on every edit or fix. */
  onValueChange?: (value: string) => void
  /** Controlled file list (one path per line; `git status --porcelain` lines also work). */
  files?: string
  /** Initial file list when uncontrolled. */
  defaultFiles?: string
  /** Called when the file list is edited. */
  onFilesChange?: (files: string) => void
  /** Paths you know are committed, e.g. from `git ls-files`. */
  trackedFiles?: string[]
  /** Start with "These paths are already committed" ticked. */
  defaultPathsTracked?: boolean
  /** Visible label; shorthand for `messages.label`. */
  label?: string
  /** Every visible string. `{line}`, `{detail}`, `{rule}`, `{count}` and friends are filled in. */
  messages?: Partial<GitignoreCheckMessages>
}

/**
 * A .gitignore editor that shows what Git will really ignore. It catches inline `#` comments, trailing tabs,
 * leading spaces, backslashes and `./`, `!` lines that can't re-include a file inside an excluded folder or are
 * overridden by a later line, `/` anchors that miss nested folders, `.env`, keys and node_modules left out, and
 * files already committed that .gitignore won't untrack (with the `git rm --cached` command).
 */
export function GitignoreCheck({
  value,
  defaultValue = "",
  onValueChange,
  files,
  defaultFiles = "",
  onFilesChange,
  trackedFiles,
  defaultPathsTracked = false,
  label,
  messages,
  rows = 7,
  id,
  className,
  ref,
  "aria-describedby": describedBy,
  ...props
}: GitignoreCheckProps) {
  const t = { ...GITIGNORE_CHECK_MESSAGES, ...messages, ...(label !== undefined && { label }) }
  const [inner, setInner] = React.useState(defaultValue)
  const [innerFiles, setInnerFiles] = React.useState(defaultFiles)
  const [pathsTracked, setPathsTracked] = React.useState(defaultPathsTracked)
  const [copied, setCopied] = React.useState(false)
  const [notice, setNotice] = React.useState("")
  const textarea = React.useRef<HTMLTextAreaElement>(null)
  const list = React.useRef<HTMLUListElement>(null)
  const refocus = React.useRef<number | null>(null)
  const autoId = React.useId()
  const inputId = id ?? autoId
  const text = typeof (value ?? inner) === "string" ? (value ?? inner) : ""
  const fileText = typeof (files ?? innerFiles) === "string" ? (files ?? innerFiles) : ""
  React.useImperativeHandle(ref, () => textarea.current as HTMLTextAreaElement)

  const entries = React.useMemo(() => parseFileList(fileText, pathsTracked, trackedFiles), [fileText, pathsTracked, trackedFiles])
  const rules = React.useMemo(() => parseGitignore(text), [text])
  const issues = React.useMemo(() => checkGitignore(text, entries), [text, entries])
  const rowsText = React.useMemo(() => toLines(text), [text])
  const counted = issues.filter((issue) => issue.severity !== "info")
  const errors = counted.filter((issue) => issue.severity === "error").length
  const fixable = counted.filter((issue) => issue.fix !== undefined)
  const verdicts = entries.map((entry) => ({ entry, verdict: checkIgnore(rules, entry.path) }))
  const summary = !text.trim() && !entries.length ? "" : counted.length ? fill(t.problems, { errors, warnings: counted.length - errors }) : t.clean
  const settled = useSettled(summary)

  const update = (next: string) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }
  const updateFiles = (next: string) => {
    if (files === undefined) setInnerFiles(next)
    onFilesChange?.(next)
  }
  React.useEffect(() => {
    if (refocus.current === null) return
    const buttons = list.current?.querySelectorAll<HTMLButtonElement>("button[data-fix]") ?? []
    ;(buttons[Math.min(refocus.current, buttons.length - 1)] ?? textarea.current)?.focus()
    refocus.current = null
  }, [text])
  const fix = (issue: GitignoreIssue, button: HTMLElement) => {
    refocus.current = [...(list.current?.querySelectorAll("button[data-fix]") ?? [])].indexOf(button)
    update(issue.fix ?? text)
  }
  /** Applies fixes one at a time, re-checking in between, so line-based fixes never collide. */
  const fixAll = () => {
    let next = text
    for (let round = 0; round < 20; round++) {
      const first = checkGitignore(next, entries).find((issue) => issue.severity !== "info" && issue.fix !== undefined)
      if (!first?.fix || first.fix === next) break
      next = first.fix
    }
    refocus.current = 0
    update(next)
  }
  const reveal = (line: number) => {
    const el = textarea.current
    if (!el) return
    const start = rowsText.slice(0, line).reduce((sum, row) => sum + row.length + (text.includes("\r\n") ? 2 : 1), text.startsWith("\uFEFF") ? 1 : 0)
    el.focus()
    el.setSelectionRange(start, start + (rowsText[line]?.length ?? 0))
  }
  const copy = async (command: string) => {
    try {
      await navigator.clipboard.writeText(command)
      setCopied(true)
      setNotice(t.copiedStatus)
      setTimeout(() => setCopied(false), 1500)
    } catch {
      setNotice(t.copyFailed)
    }
  }
  React.useEffect(() => setNotice(""), [text, fileText])

  const ruleText = (line: number) => rowsText[line]?.trim() ?? ""
  const describe = (issue: GitignoreIssue) => fill((t as Record<string, string>)[issue.kind] ?? "", { detail: issue.detail ?? "" })

  return (
    <div data-slot="gitignore-check" className={cn("grid w-full max-w-xl min-w-0 grid-cols-[minmax(0,1fr)] gap-1.5 text-sm", className)}>
      <label htmlFor={inputId} className="w-fit font-mono font-medium">
        {t.label}
      </label>
      <textarea
        ref={textarea}
        id={inputId}
        rows={rows}
        value={text}
        onChange={(event) => update(event.target.value)}
        spellCheck={false}
        autoCapitalize="none"
        autoCorrect="off"
        wrap="off"
        placeholder={t.placeholder}
        aria-invalid={errors > 0 || undefined}
        aria-describedby={[describedBy, `${inputId}-status`].filter(Boolean).join(" ")}
        className={area}
        {...props}
      />
      <span role="status" className="sr-only">
        {notice || settled}
      </span>
      <div id={`${inputId}-status`} className="mt-1.5 flex min-h-6 flex-wrap items-center justify-between gap-2 text-xs empty:hidden">
        {summary && (
          <span className={cn("flex items-center gap-1.5", counted.length ? "text-muted-foreground" : "text-emerald-700 dark:text-emerald-400")}>
            {counted.length ? <TriangleAlert aria-hidden className="size-3.5 text-amber-600 dark:text-amber-400" /> : <CircleCheck aria-hidden className="size-3.5" />}
            {summary}
          </span>
        )}
        {fixable.length > 1 && (
          <button type="button" onClick={fixAll} className={fixClass(false)}>
            <WandSparkles aria-hidden className="size-3.5" />
            {fill(t.fixAll, { count: fixable.length })}
          </button>
        )}
      </div>
      {issues.length > 0 && (
        <ul ref={list} className="grid gap-1.5 text-xs">
          {issues.map((issue, index) => {
            const Icon = icons[issue.severity]
            const stuck = issue.kind === "tracked" ? (issue.detail ?? "").split("\n") : []
            return (
              <li key={`${issue.kind}-${issue.line ?? index}`} className={cn("flex gap-1.5", tones[issue.severity])}>
                <span className="flex h-6 shrink-0 items-center">
                  <Icon aria-hidden className="size-3.5" />
                </span>
                <span className="flex min-w-0 flex-1 flex-wrap items-center gap-x-2 gap-y-1">
                  <span className="min-w-0 py-1 [overflow-wrap:anywhere]">
                    {issue.line !== undefined && (
                      <button type="button" onClick={() => reveal(issue.line!)} aria-label={fill(t.selectLine, { line: issue.line + 1 })} className="mr-1 rounded font-mono whitespace-nowrap text-muted-foreground tabular-nums underline-offset-2 outline-none hover:text-foreground hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/50">
                        {fill(t.line, { line: issue.line + 1 })}
                      </button>
                    )}
                    {describe(issue)}
                    {issue.kind === "tracked" && issue.severity === "error" && <> {t.trackedSecret}</>}
                  </span>
                  {issue.fix !== undefined && (
                    <button type="button" data-fix="" onClick={(event) => fix(issue, event.currentTarget)} className={fixClass(issue.severity === "error")}>
                      {(t as Record<string, string>)[`fix-${issue.kind}`] ?? t.fix}
                    </button>
                  )}
                  {stuck.length > 0 && (
                    <span className="grid w-full min-w-0 gap-1.5">
                      <code className="block rounded-md bg-muted px-2 py-1.5 font-mono text-foreground [overflow-wrap:anywhere] select-all">{untrackCommand(stuck)}</code>
                      <button type="button" onClick={() => copy(untrackCommand(stuck))} className={cn(fixClass(issue.severity === "error"), "w-fit")}>
                        {copied ? <CircleCheck aria-hidden className="size-3.5" /> : <Copy aria-hidden className="size-3.5" />}
                        {copied ? t.copied : t.copyCommand}
                      </button>
                    </span>
                  )}
                </span>
              </li>
            )
          })}
        </ul>
      )}
      <div className="mt-2 grid gap-1.5 border-t pt-3">
        <label htmlFor={`${inputId}-files`} className="w-fit text-xs font-medium">
          {t.filesLabel}
        </label>
        <textarea id={`${inputId}-files`} rows={4} value={fileText} onChange={(event) => updateFiles(event.target.value)} spellCheck={false} autoCapitalize="none" autoCorrect="off" wrap="off" placeholder={t.filesPlaceholder} aria-describedby={`${inputId}-files-hint ${inputId}-results-count`} className={area} />
        <p id={`${inputId}-files-hint`} className="text-xs text-muted-foreground">
          {t.filesHint}
        </p>
        <label className="flex w-fit items-center gap-2 text-xs">
          <input type="checkbox" checked={pathsTracked} onChange={(event) => setPathsTracked(event.target.checked)} className="size-4 rounded border accent-primary outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50" />
          {t.trackedLabel}
        </label>
        <div id={`${inputId}-results`} className="grid gap-1 empty:hidden">
          {verdicts.length > 0 && <p id={`${inputId}-results-count`} className="text-xs font-medium text-muted-foreground">{fill(t.results, { ignored: verdicts.filter((row) => row.verdict.ignored).length, total: verdicts.length })}</p>}
          {verdicts.length > 0 && (
            <ul className="grid gap-1 text-xs">
              {verdicts.slice(0, SHOWN).map(({ entry, verdict }) => {
                const risky = !verdict.ignored && sensitiveKind(entry.path) !== undefined
                const stuck = verdict.ignored && entry.tracked
                const reason = verdict.ignored
                  ? verdict.blocked
                    ? fill(t.blocked, { neg: verdict.blocked.line + 1 })
                    : fill(verdict.viaDir ? t.ignoredDir : t.ignoredBy, { dir: verdict.viaDir ?? "", line: verdict.rule.line + 1, rule: ruleText(verdict.rule.line) })
                  : verdict.rule
                    ? fill(t.includedBy, { line: verdict.rule.line + 1, rule: ruleText(verdict.rule.line) })
                    : t.kept
                const Icon = risky ? FileWarning : verdict.ignored ? EyeOff : CircleCheck
                return (
                  <li key={entry.path} className={cn("grid grid-cols-[auto_minmax(0,1fr)] gap-x-1.5", risky ? "text-red-700 dark:text-red-400" : stuck ? "text-amber-700 dark:text-amber-400" : "text-muted-foreground")}>
                    <Icon aria-hidden className="mt-0.5 size-3.5" />
                    <span className="min-w-0 [overflow-wrap:anywhere]">
                      <span className={cn("font-mono", !verdict.ignored && !risky && "text-foreground")}>{entry.path}</span> · {stuck ? t.stillTracked : reason}
                    </span>
                  </li>
                )
              })}
            </ul>
          )}
          {verdicts.length > SHOWN && <p className="text-xs text-muted-foreground">{fill(t.more, { count: verdicts.length - SHOWN })}</p>}
        </div>
      </div>
    </div>
  )
}

/**
 * A dependency-free .gitignore engine that follows git's rules (git-scm.com/docs/gitignore and dir.c):
 * BOM and CR are dropped, unescaped trailing spaces are trimmed (tabs are not), `#` is only a comment at the
 * start of a line, the last matching line wins, a slash at the start or middle anchors the pattern, a trailing
 * slash matches directories only, and a file can't be re-included when a parent directory is excluded.
 */

export interface GitignoreRule {
  /** 0-based source line. */
  line: number
  /** The line as written (CR removed). */
  source: string
  /** Pattern after trimming, without `!` and the trailing `/`. */
  pattern: string
  negated: boolean
  dirOnly: boolean
  /** Has a leading or middle slash, so it only matches from the .gitignore's folder. */
  anchored: boolean
  regex: RegExp | null
}

export type IgnoreVerdict =
  | { ignored: false; rule?: GitignoreRule }
  /** `viaDir`: an excluded parent folder decides it; `blocked`: the file's own `!` line that can't re-include it. */
  | { ignored: true; rule: GitignoreRule; viaDir?: string; blocked?: GitignoreRule }

export type GitignoreIssueKind =
  | "inline-comment" | "trailing-tab" | "trailing-space" | "leading-space" | "backslash" | "dot-slash"
  | "dir-blocks-negation" | "negation-overridden" | "anchored-misses" | "not-ignored" | "tracked"

export interface GitignoreIssue {
  kind: GitignoreIssueKind
  severity: "error" | "warning" | "info"
  /** 0-based .gitignore line, when the issue is about a line. */
  line?: number
  /** The file path or detail filled into the message. */
  detail?: string
  /** A rewrite of the whole .gitignore that fixes it. */
  fix?: string
}

export interface FileEntry {
  path: string
  tracked: boolean
}

export const toLines = (text: string) => text.replace(/^\uFEFF/, "").split(/\r\n|\r|\n/)
const eol = (text: string) => (/\r\n/.test(text) ? "\r\n" : "\n")
const bom = (text: string) => (text.startsWith("\uFEFF") ? "\uFEFF" : "")
/** Rebuilds the text keeping its BOM and line endings. */
const join = (original: string, lines: string[]) => bom(original) + lines.join(eol(original))

/** git's trim_trailing_spaces: drop unescaped trailing spaces only. */
export function trimTrailingSpaces(line: string) {
  let lastSpace = -1
  for (let i = 0; i < line.length; i++) {
    const ch = line[i]
    if (ch === " ") { if (lastSpace < 0) lastSpace = i }
    else if (ch === "\\") { i++; lastSpace = -1 }
    else lastSpace = -1
  }
  return lastSpace < 0 ? line : line.slice(0, lastSpace)
}

/** Turns a wildmatch (WM_PATHNAME) pattern into a RegExp, or null when git would never match it. */
export function patternToRegex(pattern: string): RegExp | null {
  let out = ""
  for (let i = 0; i < pattern.length; i++) {
    const ch = pattern[i]
    if (ch === "*") {
      const start = i
      while (pattern[i + 1] === "*") i++
      const double = i > start
      const before = start === 0 || pattern[start - 1] === "/"
      const after = i + 1 === pattern.length || pattern[i + 1] === "/"
      if (double && before && after) {
        if (i + 1 === pattern.length) out += ".*"
        else { out += "(?:.*/)?"; i++ }
      } else out += "[^/]*"
    } else if (ch === "?") out += "[^/]"
    else if (ch === "[") {
      // wildmatch brackets: `!`/`^` negates, a leading `]` is literal, `\x` escapes, `[:class:]` names a class.
      let j = i + 1
      const negate = pattern[j] === "!" || pattern[j] === "^"
      if (negate) j++
      let body = ""
      let closed = false
      let prev = ""
      for (let first = true; j < pattern.length; j++, first = false) {
        const c = pattern[j]
        if (c === "]" && !first) { closed = true; break }
        if (c === "-" && prev && pattern[j + 1] !== undefined && pattern[j + 1] !== "]") {
          // A reversed range (z-a) matches only its first character in git; JS would throw.
          const escaped = pattern[j + 1] === "\\" && j + 2 < pattern.length
          if ((escaped ? pattern[j + 2] : pattern[j + 1]) < prev) { j += escaped ? 2 : 1; prev = ""; continue }
        }
        if (c === "\\" && j + 1 < pattern.length) { const lit = pattern[++j]; body += /\w/.test(lit) ? lit : "\\" + lit; prev = lit; continue }
        prev = c
        if (c === "[" && pattern[j + 1] === ":") {
          const end = pattern.indexOf(":]", j + 2)
          if (end > 0) { prev = ""; body += ({ alpha: "a-zA-Z", digit: "0-9", alnum: "a-zA-Z0-9", upper: "A-Z", lower: "a-z", space: "\\s", blank: " \\t", xdigit: "0-9a-fA-F", punct: "!-/:-@\\[-`{-~" } as Record<string, string>)[pattern.slice(j + 2, end)] ?? ""; j = end + 1; continue }
        }
        body += /[\]\\^]/.test(c) ? "\\" + c : c
      }
      // git's wildmatch aborts on an unclosed bracket, so the line never matches anything.
      if (!closed) return null
      out += `[${negate ? "^/" : ""}${body}]`
      i = j
    } else if (ch === "\\") {
      if (i + 1 >= pattern.length) return null
      out += pattern[++i].replace(/[.*+?^${}()|[\]\\/]/g, "\\$&")
    } else out += ch.replace(/[.*+?^${}()|[\]\\/]/g, "\\$&")
  }
  try { return new RegExp(`^${out}$`) } catch { return null }
}

export function parseGitignore(text: string): GitignoreRule[] {
  const rules: GitignoreRule[] = []
  toLines(typeof text === "string" ? text : "").forEach((source, line) => {
    let pattern = trimTrailingSpaces(source)
    if (!pattern || pattern.startsWith("#")) return
    const negated = pattern.startsWith("!")
    if (negated) pattern = pattern.slice(1)
    if (pattern.startsWith("\\#") || pattern.startsWith("\\!")) pattern = pattern.slice(1)
    const dirOnly = pattern.endsWith("/") && !pattern.endsWith("\\/")
    if (dirOnly) pattern = pattern.replace(/\/+$/, "")
    if (!pattern) return
    const anchored = pattern.includes("/")
    if (pattern.startsWith("/")) pattern = pattern.slice(1)
    rules.push({ line, source, pattern, negated, dirOnly, anchored, regex: patternToRegex(pattern) })
  })
  return rules
}

const normalizePath = (path: string) => path.replace(/[\r\n]+/g, "").replace(/\\/g, "/").replace(/^\.\//, "").replace(/^\/+/, "").replace(/\/{2,}/g, "/")

function ruleMatches(rule: GitignoreRule, path: string, isDir: boolean) {
  if (!rule.regex || (rule.dirOnly && !isDir)) return false
  return rule.regex.test(rule.anchored ? path : path.slice(path.lastIndexOf("/") + 1))
}

/** The last rule matching this exact path, ignoring parents. */
function lastMatch(rules: GitignoreRule[], path: string, isDir: boolean) {
  for (let i = rules.length - 1; i >= 0; i--) if (ruleMatches(rules[i], path, isDir)) return rules[i]
  return undefined
}

/** Directory verdicts repeat across files, so they're cached per parsed rule list. */
const dirCache = new WeakMap<GitignoreRule[], Map<string, GitignoreRule | null>>()
function dirMatch(rules: GitignoreRule[], dir: string) {
  let cache = dirCache.get(rules)
  if (!cache) dirCache.set(rules, (cache = new Map()))
  if (!cache.has(dir)) cache.set(dir, lastMatch(rules, dir, true) ?? null)
  return cache.get(dir) ?? undefined
}

/** Whether git ignores the path, and which line decides it. A path ending in "/" is a directory. */
export function checkIgnore(rules: GitignoreRule[], rawPath: string): IgnoreVerdict {
  const isDir = rawPath.trim().endsWith("/")
  const path = normalizePath(rawPath).replace(/\/$/, "")
  if (!path) return { ignored: false }
  const parts = path.split("/")
  for (let depth = 1; depth < parts.length; depth++) {
    const dir = parts.slice(0, depth).join("/")
    const rule = dirMatch(rules, dir)
    if (rule && !rule.negated) {
      const own = lastMatch(rules, path, isDir)
      return { ignored: true, rule, viaDir: dir, blocked: own?.negated ? own : undefined }
    }
  }
  const rule = lastMatch(rules, path, isDir)
  return rule && !rule.negated ? { ignored: true, rule } : { ignored: false, rule }
}

/** Reads a pasted file list: plain paths, `git ls-files` output or `git status --porcelain` lines. */
export function parseFileList(text: string, trackedByDefault = false, tracked: string[] = []): FileEntry[] {
  const known = new Set(tracked.map(normalizePath))
  const seen = new Set<string>()
  const entries: FileEntry[] = []
  for (const raw of toLines(typeof text === "string" ? text : "")) {
    if (!raw.trim() || raw.trim().startsWith("#")) continue
    const status = /^([ MADRCU?!T]{2}) (.+)$/.exec(raw)
    let path = status ? status[2] : raw
    if (status && /->/.test(path)) path = path.split("->").pop() ?? path
    path = path.trim().replace(/^"(.*)"$/, "$1")
    const key = normalizePath(path).replace(/\/$/, "")
    if (!key || seen.has(key) || key.length > 4096) continue
    seen.add(key)
    const isTracked = status ? !["??", "!!"].includes(status[1]) : trackedByDefault || known.has(key)
    entries.push({ path: path.trim().endsWith("/") ? `${key}/` : key, tracked: isTracked })
    if (entries.length >= 2000) break
  }
  return entries
}

const SENSITIVE: [RegExp, string][] = [
  [/(^|\/)\.env(\.(?!example$|sample$|template$|dist$)[^/]+)?$/i, ".env"],
  [/\.(pem|key|p12|pfx|jks|keystore)$/i, "key"],
  [/(^|\/)id_(rsa|dsa|ecdsa|ed25519)$/, "key"],
  [/(^|\/)(credentials(\.json)?|service-account[^/]*\.json|\.npmrc|\.netrc|\.pypirc|\.git-credentials)$/i, "key"],
  [/\.tfstate(\.backup)?$/i, "key"],
  [/(^|\/)node_modules\//, "node_modules"],
]
export const sensitiveKind = (path: string) => SENSITIVE.find(([re]) => re.test(normalizePath(path)))?.[1]

/** Lines to append so each kind is ignored, keeping example env files committable. */
const ADDITIONS: Record<string, string[]> = { ".env": [".env", ".env.*", "!.env.example"], key: ["*.pem", "*.key", "id_rsa", "id_ed25519"], node_modules: ["node_modules/"] }
/** The line that ignores this exposed key-like file: its extension (*.pem, *.tfstate), or its name (credentials.json, .npmrc). */
function keyLines(path: string) {
  const name = normalizePath(path).split("/").pop() ?? path
  if (/\.tfstate(\.backup)?$/i.test(name)) return ["*.tfstate", "*.tfstate.*"]
  const ext = /\.(pem|key|p12|pfx|jks|keystore)$/i.exec(name)
  if (ext) return [`*.${ext[1]}`]
  if (/^service-account[^/]*\.json$/i.test(name)) return ["service-account*.json"]
  return [name.replace(/([*?[\]\\!#])/g, "\\$1")]
}
/** Paths probed when no file list is given (node_modules only when the list shows a Node project). */
const PROBES: [string, string][] = [[".env", ".env"], [".env.local", ".env"], ["deploy.pem", "key"], ["id_rsa", "key"]]

function append(text: string, lines: string[]) {
  const rows = toLines(text)
  while (rows.length && !rows[rows.length - 1].trim()) rows.pop()
  return join(text, [...rows, ...lines, ""])
}
function replaceLine(text: string, line: number, next: string | null) {
  const rows = toLines(text)
  if (next === null) rows.splice(line, 1)
  else rows[line] = next
  return join(text, rows)
}
const quotePath = (path: string) => (/^[\w./@+-]+$/.test(path) ? path : `'${path.replace(/'/g, `'\\''`)}'`)

/** One `git rm --cached` command that untracks the paths but keeps them on disk. */
export const untrackCommand = (paths: string[]) => `git rm -r --cached -- ${paths.map((p) => quotePath(p.replace(/\/$/, ""))).join(" ")}`

/** Everything wrong with the .gitignore text and, given files, with what it actually does to them. */
export function checkGitignore(text: string, files: FileEntry[] = []): GitignoreIssue[] {
  const source = typeof text === "string" ? text : ""
  const issues: GitignoreIssue[] = []
  const rows = toLines(source)
  rows.forEach((row, line) => {
    if (!row.trim() || row.trimStart().startsWith("#")) return
    if (/[\t\u00a0]+$/.test(row)) issues.push({ kind: "trailing-tab", severity: "error", line, fix: replaceLine(source, line, row.replace(/[\s\u00a0]+$/, "")) })
    else if (/[^\\] +$/.test(row)) issues.push({ kind: "trailing-space", severity: "info", line, fix: replaceLine(source, line, trimTrailingSpaces(row)) })
    if (/^\s+\S/.test(row)) issues.push({ kind: "leading-space", severity: "error", line, fix: replaceLine(source, line, row.trimStart()) })
    const comment = /\s+#.*$/.exec(row)
    if (comment && !row.startsWith("#") && !/\\#/.test(row)) issues.push({ kind: "inline-comment", severity: "error", line, detail: row.slice(0, comment.index).trim(), fix: replaceLine(source, line, row.slice(0, comment.index)) })
    if (/\\(?![#! *?[\\])/.test(row) && /\w\\\w/.test(row)) issues.push({ kind: "backslash", severity: "error", line, fix: replaceLine(source, line, row.replace(/\\/g, "/")) })
    if (/^!?\.\//.test(row.trim())) issues.push({ kind: "dot-slash", severity: "error", line, fix: replaceLine(source, line, row.replace("./", "/")) })
  })

  const rules = parseGitignore(source)
  rules.forEach((rule, index) => {
    if (!rule.negated) return
    // A negation can't reach inside a directory an earlier (or later) rule excludes.
    const parts = rule.pattern.split("/")
    for (let depth = 1; depth < parts.length; depth++) {
      const dir = parts.slice(0, depth).join("/")
      if (/[*?[]/.test(dir)) break
      const blocker = lastMatch(rules, dir, true)
      if (blocker && !blocker.negated) {
        // `logs/` → `logs/*` style: ignore the folder's contents instead, so `!` can re-include a file in it.
        const contents = `${blocker.anchored ? "/" : "**/"}${blocker.pattern}/*`
        issues.push({ kind: "dir-blocks-negation", severity: "error", line: rule.line, detail: blocker.source.trim(), fix: depth === parts.length - 1 ? replaceLine(source, blocker.line, contents) : undefined })
        return
      }
    }
    // A literal negation followed by a rule that ignores it again: the later line wins.
    if (/[*?[\\]/.test(rule.pattern)) return
    const later = rules.slice(index + 1).find((other) => !other.negated && ruleMatches(other, rule.pattern, false))
    if (later) {
      const moved = toLines(source)
      const [row] = moved.splice(rule.line, 1)
      moved.splice(later.line, 0, row)
      issues.push({ kind: "negation-overridden", severity: "error", line: rule.line, detail: later.source.trim(), fix: join(source, moved) })
    }
  })

  // Anchored rules that miss the same name deeper in the tree.
  const anchoredMisses = new Map<number, string>()
  for (const file of files) {
    const verdict = checkIgnore(rules, file.path)
    if (verdict.ignored) continue
    const parts = normalizePath(file.path).split("/")
    for (const rule of rules) {
      if (rule.negated || !rule.anchored || rule.pattern.includes("/") || !rule.regex || anchoredMisses.has(rule.line)) continue
      const hit = parts.findIndex((part, i) => i > 0 && rule.regex!.test(part) && (!rule.dirOnly || i < parts.length - 1))
      if (hit > 0) anchoredMisses.set(rule.line, file.path)
    }
  }
  for (const [line, path] of anchoredMisses) issues.push({ kind: "anchored-misses", severity: "warning", line, detail: path, fix: replaceLine(source, line, rows[line].replace(/^(\s*!?)\//, "$1")) })

  // Sensitive files that would be committed, from the list or from probes.
  const exposed = new Map<string, string[]>()
  const probes: [string, string][] = files.length ? files.map((file) => [file.path, sensitiveKind(file.path) ?? ""]) : PROBES
  for (const [path, kind] of probes) {
    if (!kind || checkIgnore(rules, path).ignored) continue
    exposed.set(kind, [...(exposed.get(kind) ?? []), path])
  }
  for (const [kind, paths] of exposed) {
    // From a real file list it's a leak; from probes it's a likely one.
    // Almost no template ignores *.pem, so a key probe alone is a hint, not a count; a missing .env still warns.
    const severity = !files.length ? (kind === "key" ? "info" : "warning") : kind === "node_modules" ? "warning" : "error"
    issues.push({ kind: "not-ignored", severity, detail: paths.slice(0, 3).join(", ") + (paths.length > 3 ? ` +${paths.length - 3}` : ""), fix: append(source, [...new Set(kind === "key" ? (files.length ? paths.flatMap(keyLines) : ADDITIONS.key) : ADDITIONS[kind])].filter((add) => !rows.some((row) => row.trim() === add))) })
  }

  // Tracked files a rule now matches: .gitignore never untracks them.
  const stuck = files.filter((file) => file.tracked && checkIgnore(rules, file.path).ignored)
  if (stuck.length) issues.push({ kind: "tracked", severity: stuck.some((file) => sensitiveKind(file.path) && sensitiveKind(file.path) !== "node_modules") ? "error" : "warning", detail: stuck.map((file) => file.path).join("\n") })
  return issues
}
